import app from 'flarum/forum/app';
import DeckColumns from 'ext:flarum/deck/forum/extenders/DeckColumns';
import DiscussionListSource from 'ext:flarum/deck/forum/columns/DiscussionListSource';
import extractText from 'flarum/common/utils/extractText';
import highlight from 'flarum/common/helpers/highlight';
import tagIcon from '../common/helpers/tagIcon';
/** A Tag column for flarum/deck. Only used while Deck is enabled; see extend.ts. */
export default function extendDeck() {
  return [new DeckColumns().add('flarum-tags.tag', {
    icon: 'fas fa-tag',
    label: () => extractText(app.translator.trans('flarum-tags.forum.deck.column_label')),
    title: config => app.store.getBy('tags', 'slug', String(config.params.slug))?.name() ?? String(config.params.slug),
    isAvailable: () => true,
    fields: () => [{
      key: 'tag',
      label: app.translator.trans('flarum-tags.forum.deck.tag_label'),
      placeholder: extractText(app.translator.trans('flarum-tags.forum.deck.tag_placeholder')),
      // The forum payload already has every tag the member can see.
      search: {
        minLength: 1,
        find: query => Promise.resolve(app.store.all('tags').filter(tag => tag.name().toLowerCase().includes(query.toLowerCase())).slice(0, 8)),
        display: (tag, query) => [tagIcon(tag), ' ', highlight(tag.name(), query)],
        label: tag => tag.name(),
        params: tag => ({
          slug: tag.slug()
        })
      }
    }],
    // `tags` is the param this extension's DiscussionListState hook reads.
    createSource: config => new DiscussionListSource({
      tags: String(config.params.slug)
    })
  }, 70)];
}